import React, { useState, useEffect, useRef, useCallback } from "react";
import { Form, Input, message } from "antd";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import Spinner from "../components/Spinner";

const Login = () => {
  const [loading, setLoading] = useState(false);
  const [form] = Form.useForm();
  const navigate = useNavigate();
  const buttonRef = useRef(null);
  const [formValues, setFormValues] = useState({
    email: "",
    password: "",
  });

  // Memoized form validation check
  const isFormValid = useCallback(() => {
    return formValues.email && formValues.password;
  }, [formValues]);

  const submitHandler = async (values) => {
    try {
      setLoading(true);
      const { data } = await axios.post("/api/v1/users/login", values);
      setLoading(false);
      message.success("login success");
      localStorage.setItem(
        "user",
        JSON.stringify({ ...data.user, password: "" })
      );
      navigate("/");
    } catch (error) {
      setLoading(false);
      message.error("Invalid credentials");
    }
  };

  // Prevent logged-in users from accessing login page
  useEffect(() => {
    if (localStorage.getItem("user")) {
      navigate("/");
    }
  }, [navigate]);

  // Button movement effect
  useEffect(() => {
    const button = buttonRef.current;
    if (!button) return;

    const handleMouseMove = (event) => {
      if (isFormValid()) return;

      const distanceBetween = (p1x, p1y, p2x, p2y) => {
        const dx = p1x - p2x;
        const dy = p1y - p2y;
        return Math.sqrt(dx * dx + dy * dy);
      };

      const radius = Math.max(
        button.offsetWidth * 0.75,
        button.offsetHeight * 0.75,
        100
      );
      
      const buttonRect = button.getBoundingClientRect();
      const bx = buttonRect.left + buttonRect.width / 2;
      const by = buttonRect.top + buttonRect.height / 2;

      const dist = distanceBetween(event.clientX, event.clientY, bx, by);
      const angle = Math.atan2(event.clientY - by, event.clientX - bx);

      const ox = -1 * Math.cos(angle) * Math.max(radius - dist, 0);
      const oy = -1 * Math.sin(angle) * Math.max(radius - dist, 0);

      button.style.transform = `translate(${ox}px, ${oy}px) rotateX(${oy / 2}deg) rotateY(${-ox / 2}deg)`;
      button.style.boxShadow = `0px ${Math.abs(oy)}px ${(Math.abs(oy) / radius) * 40}px rgba(0, 0, 0, 0.15)`;
    };

    // Only add listener if form is invalid
    if (!isFormValid()) {
      document.addEventListener("mousemove", handleMouseMove);
    }

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      // Reset styles when effect cleans up
      if (button) {
        button.style.transform = '';
        button.style.boxShadow = '';
      }
    };
  }, [formValues]); // Re-run when form values change

  return (
    <>
      <div className="resgister-page">
        {loading && <Spinner />}
        <Form
          form={form}
          layout="vertical"
          onFinish={submitHandler}
          onValuesChange={(_, values) => setFormValues(values)}
        >
          <h1>Login Form</h1>

          <Form.Item label="Email" name="email">
            <Input type="email" />
          </Form.Item>
          <Form.Item label="Password" name="password">
            <Input type="password" />
          </Form.Item>
          <div className="d-flex justify-content-between">
            <Link to="/register">Not a user ? Click here to register</Link>
            <button
              ref={buttonRef}
              className="btn btn-primary mx-2"
              style={{
                transition: "all 0.1s ease",
                transformStyle: "preserve-3d"
              }}
            >
              Login
            </button>
          </div>
        </Form>
      </div>
    </>
  );
};

export default Login;