

import './Header.css';
import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { message } from "antd";

const Header = () => {
  const [loginUser, setLoginUser] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));
    if (user) {
      setLoginUser(user);
    }
  }, []);

  const logoutHandler = () => {
    localStorage.removeItem("user");
    message.success("Logout Successfully");
    navigate("/login");
  };

  return (
    <nav
      className="navbar navbar-expand-lg shadow-sm"
      style={{
        background: "linear-gradient(to right, #ffffff, #f7f9fc)",
        borderBottom: "1px solid #eaeaea",
        height: "64px",
      }}
    >
      <div className="container-fluid d-flex justify-content-between align-items-center px-3 px-md-4">
        
        <Link
          className="navbar-brand text-dark fw-bold fs-4 text-center"
          to="/"
          style={{
            fontFamily: "Segoe UI, sans-serif",
            letterSpacing: "1px",
            whiteSpace: "nowrap",
            color: "#000",  
          }}
        >
          DhanVeda
        </Link>





        {loginUser && (
          <div className="d-flex align-items-center gap-2 position-absolute end-0 me-3">
            <span
              className="text-secondary mb-0 user-info"
              style={{
                fontWeight: "500",
                fontSize: "0.9rem",
                overflow: "hidden",
                textOverflow: "ellipsis",
                maxWidth: "100px",
              }}
              title={loginUser.name}
            >
              {loginUser.name}
            </span>
            <button
              className="btn btn-primary btn-sm"
              onClick={logoutHandler}
              style={{
                borderRadius: "8px",
                fontWeight: "500",
                padding: "4px 12px",
                fontSize: "0.85rem",
              }}
            >
              Logout
            </button>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Header;


