


import React from "react";
import { Progress } from "antd";

const Analytics = ({ allTransection }) => {
  const categories = [
    "salary",
    "tip",
    "project",
    "food",
    "movie",
    "bills",
    "medical",
    "fee",
    "others",
  ];

  // Total transaction
  const totalTransaction = allTransection.length;
  const totalIncomeTransactions = allTransection.filter(
    (transaction) => transaction.type === "income"
  );
  const totalExpenseTransactions = allTransection.filter(
    (transaction) => transaction.type === "expense"
  );

  const totalIncomePercent =
    (totalIncomeTransactions.length / totalTransaction) * 100;
  const totalExpensePercent =
    (totalExpenseTransactions.length / totalTransaction) * 100;

  // Total turnover
  const totalTurnover = allTransection.reduce(
    (acc, transaction) => acc + transaction.amount,
    0
  );
  const totalIncomeTurnover = totalIncomeTransactions.reduce(
    (acc, transaction) => acc + transaction.amount,
    0
  );
  const totalExpenseTurnover = totalExpenseTransactions.reduce(
    (acc, transaction) => acc + transaction.amount,
    0
  );

  // Wealth Calculation
  const wealth = totalIncomeTurnover - totalExpenseTurnover;

  const totalIncomeTurnoverPercent =
    (totalIncomeTurnover / totalTurnover) * 100;
  const totalExpenseTurnoverPercent =
    (totalExpenseTurnover / totalTurnover) * 100;

  return (
    <>
      {/* 💰 Net Balance Section */}
      <div className="text-center my-3">
        <h4
          style={{
            fontWeight: "bold",
            color: wealth >= 0 ? "#9ACD32" : "crimson",
          }}
        >
          💰 Net Balance: {wealth}
        </h4>
      </div>

      {/* Main Card Grid */}
      <div className="row m-3">
        {/* Total Transactions Card */}
        <div className="col-md-3">
          <div className="card">
            <div className="card-header">
              Total Transactions: {totalTransaction}
            </div>
            <div className="card-body">
              <h5 style={{ color: "#9ACD32" }}>
                Income: {totalIncomeTransactions.length}
              </h5>
              <h5 style={{ color: "crimson" }}>
                Expense: {totalExpenseTransactions.length}
              </h5>
              <div className="d-flex flex-column align-items-center">
                <Progress
                  type="circle"
                  strokeColor={"#9ACD32"}
                  className="mx-2"
                  percent={totalIncomePercent.toFixed(0)}
                />
                <Progress
                  type="circle"
                  strokeColor={"crimson"}
                  className="mx-2 mt-3"
                  percent={totalExpensePercent.toFixed(0)}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Total Turnover Card */}
        <div className="col-md-3">
          <div className="card">
            <div className="card-header">Total TurnOver: {totalTurnover}</div>
            <div className="card-body">
              <h5 style={{ color: "#9ACD32" }}>Income: {totalIncomeTurnover}</h5>
              <h5 className="text-danger">Expense: {totalExpenseTurnover}</h5>
              <div>
                <Progress
                  type="circle"
                  strokeColor={"#9ACD32"}
                  className="mx-2"
                  percent={totalIncomeTurnoverPercent.toFixed(0)}
                />
                <Progress
                  type="circle"
                  strokeColor={"crimson"}
                  className="mx-2 mt-3"
                  percent={totalExpenseTurnoverPercent.toFixed(0)}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Categorywise Income Card */}
        <div className="col-md-3">
          <h6 className="p-2 text-light" style={{ backgroundColor: "#9ACD32" }}>
            Categorywise Income
          </h6>
          {categories.map((category) => {
            const amount = allTransection
              .filter(
                (transaction) =>
                  transaction.type === "income" &&
                  transaction.category?.toLowerCase() === category.toLowerCase()
              )
              .reduce((acc, transaction) => acc + transaction.amount, 0);
            return (
              amount > 0 && (
                <div className="card mt-2" key={category}>
                  <div className="card-body">
                    <h6>{category}</h6>
                    <Progress
                      percent={((amount / totalIncomeTurnover) * 100).toFixed(0)}
                      strokeColor="#9ACD32"
                    />
                  </div>
                </div>
              )
            );
          })}
        </div>

        {/* Categorywise Expense Card */}
        <div className="col-md-3">
          <h6 className="p-2 text-light" style={{ backgroundColor: "crimson" }}>
            Categorywise Expense
          </h6>
          {categories.map((category) => {
            const amount = allTransection
              .filter(
                (transaction) =>
                  transaction.type === "expense" &&
                  transaction.category?.toLowerCase() === category.toLowerCase()
              )
              .reduce((acc, transaction) => acc + transaction.amount, 0);
            return (
              amount > 0 && (
                <div className="card mt-2" key={category}>
                  <div className="card-body">
                    <h6>{category}</h6>
                    <Progress
                      percent={((amount / totalExpenseTurnover) * 100).toFixed(0)}
                      strokeColor="crimson"
                    />
                  </div>
                </div>
              )
            );
          })}
        </div>
      </div>
    </>
  );
};

export default Analytics;
